<div x-data="{open:false}" class="relative" @keydown.escape.window="open=false"><button @click="open=!open" class="min-h-11 rounded-lg border px-4" :aria-expanded="open">{{ __('checkout.cart') }} ({{ $items->sum('qty') }})</button><div x-show="open" x-cloak @click.outside="open=false" class="absolute right-0 z-40 mt-3 w-72 rounded-xl border bg-white p-5 shadow-xl"><h2 class="font-semibold">{{ __('checkout.cart') }}</h2>@forelse($items as $item)<p class="py-3">{{ $item->product?->name ?? __('checkout.product_unavailable') }} × {{ $item->qty }}</p>@empty<p class="py-4">{{ __('checkout.empty_cart') }}</p>@endforelse<a href="{{ route('cart') }}" class="inline-flex min-h-11 items-center rounded-lg bg-brand px-4 text-white">{{ __('checkout.view_cart') }}</a></div></div>